require_once __DIR__.'/config/config.php';require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';$id=(int)($_GET['id']??0);$takimSt=$pdo->prepare("SELECT t.*,l.sezon_id,s.sezon_adi FROM takimlar t JOIN gruplar g ON g.id=t.grup_id JOIN ligler l ON l.id=g.lig_id LEFT JOIN sezonlar s ON s.id=l.sezon_id WHERE t.id=?");$takimSt->execute([$id]);$t=$takimSt->fetch();if(!$t)exit('Takım bulunamadı.');$st=$pdo->prepare("SELECT m.*,ev.takim_adi ev,dep.takim_adi dep,g.grup_adi FROM maclar m JOIN gruplar g ON g.id=m.grup_id JOIN ligler l ON l.id=g.lig_id JOIN takimlar ev ON ev.id=m.ev_sahibi_id JOIN takimlar dep ON dep.id=m.deplasman_id WHERE (m.ev_sahibi_id=? OR m.deplasman_id=?) AND l.sezon_id=? ORDER BY COALESCE(m.tarih,'1000-01-01') DESC,m.id DESC");$st->execute([$id,$id,$t['sezon_id']]);$maclar=$st->fetchAll();$sayfa_baslik=$t['takim_adi'].' Maçları';$aktif='takimlar';require __DIR__.'/includes/header.php';$takimSt->execute([$id]);$t=$takimSt->fetch();?>
